#include "can_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void can_lut_wr_std (Can_Dev_Id can_dev_id , UInt16 table_index_32 , UInt16 id_std , Boolean _0_or_1_)
{
  can_lut_wr_16 ((table_index_32 << 1) + !! _0_or_1_ , id_std | (UInt16) can_dev_id << 13) ;
}

//--------------------------------------------------------------------------//

void can_lut_wr_std_x (Can_Dev_Id can_dev_id , UInt16 table_index_32)
{
  can_lut_wr_std (can_dev_id , table_index_32 , 0x1FFF , 1) ;
}

//--------------------------------------------------------------------------//

void can_lut_wr_ext (Can_Dev_Id can_dev_id , UInt16 table_index_32 , UInt32 id_ext)
{
  CAN_AFRAM [table_index_32] = id_ext | ((UInt32) can_dev_id << 29) ;
}

//--------------------------------------------------------------------------//

void can_lut_wr_16 (UInt16 table_index_16 , UInt16 data)
{
  volatile UInt32 * entry = & CAN_AFRAM [table_index_16 >> 1] ;

  if (table_index_16 & 1)
    {
      *entry &= 0xFFFF0000    ;
      *entry |= (UInt32) data ;
    }
  else
    {
      *entry &= 0x0000FFFF          ;
      *entry |= (UInt32) data << 16 ;
    }
}

